        elementTimeline = prepTextForAnimation(element);
      } else {
        elementTimeline = animateElement(element, {
          delay: elementDelay
        });
      }

      // Add to row timeline
      if (elementTimeline) {
        rowTimeline.add(elementTimeline, rowDelay);
      }
    });

    // Add a small buffer to ensure the row is complete
    rowTimeline.to({}, { duration: 0.05 });
  });
};

/**
 * Main function to organize and animate content by rows
 */
export const animateAllContent = async () => {
  // Clear any existing animations
  clearAllAnimations();

  // Get the main content container
  const mainContent = document.querySelector('.main-content');
  if (!mainContent) return;

  // Fade in the main content container
  gsap.fromTo(mainContent, 
    { 
      opacity: 0.8 
    },
    { 
      opacity: 1,
      duration: 0.3,
      ease: "power1.out"
    }
  );

  // Find all visible elements to animate
  const allElements = Array.from(mainContent.querySelectorAll('h1, h2, h3, h4, h5, h6, p, a, li, img, .category-item, span:not(.alien-char)'))
    .filter(el => {
      // Skip hidden elements and those marked as non-animating
      if (el.classList.contains('no-animate')) return false;
      if (el.classList.contains('alien-animating')) return false;
      if (el.closest('.no-animate')) return false;
      if (window.getComputedStyle(el).display === 'none') return false;

      // Skip certain elements
      const skipSelectors = ['.alien-title', 'button', 'input', '.alien-animation-wrapper', '.alien-char'];
      return !skipSelectors.some(selector => 
        el.matches && el.matches(selector)
      );
    });

  // Sort by vertical position
  allElements.sort((a, b) => {
    const rectA = a.getBoundingClientRect();
    const rectB = b.getBoundingClientRect();

    // Elements within 5px of each other vertically are considered on the same row
    if (Math.abs(rectA.top - rectB.top) < 5) {
      return rectA.left - rectB.left; // Sort by horizontal position in the same row
    }

    return rectA.top - rectB.top; // Sort by vertical position for different rows
  });

  // Group elements by row
  const rows = [];
  let currentTop = -1;
  let currentRow = [];

  allElements.forEach(element => {
    const rect = element.getBoundingClientRect();

    // If this is a new row
    if (currentTop === -1 || rect.top > currentTop + 5) {
      if (currentRow.length > 0) {
        rows.push(currentRow);
      }
      currentRow = [element];
      currentTop = rect.top;
    } else {
      currentRow.push(element);
    }
  });

  // Add the last row if it exists
  if (currentRow.length > 0) {
    rows.push(currentRow);
  }

  // Animate rows sequentially
  for (let i = 0; i < rows.length; i++) {
    await animateRow(rows[i], i);

    // Small delay between rows
    await new Promise(resolve => setTimeout(resolve, 40)); // Slightly longer delay between rows
  }

  // Handle special case for categories
  const categoryContainers = document.querySelectorAll('.categories, .subcategories, .category-links');
  if (categoryContainers.length) {
    gsap.fromTo(categoryContainers, 
      { opacity: 0, y: 5 },
      { 
        opacity: 1, 
        y: 0, 
        duration: 0.3,
        ease: "power1.out",
        stagger: 0.1
      }
    );

    // Animate category items if not already animated
    const categoryItems = document.querySelectorAll('.category-item:not(.alien-animating)');
    if (categoryItems.length) {
      // Sort by vertical position
      const sortedItems = Array.from(categoryItems).sort((a, b) => {
        const rectA = a.getBoundingClientRect();
        const rectB = b.getBoundingClientRect();

        if (Math.abs(rectA.top - rectB.top) < 5) {
          return rectA.left - rectB.left;
        }

        return rectA.top - rectB.top;
      });

      // Group by rows
      const itemRows = [];
      let currentItemTop = -1;
      let currentItemRow = [];

      sortedItems.forEach(item => {
        const rect = item.getBoundingClientRect();

        if (currentItemTop === -1 || rect.top > currentItemTop + 5) {
          if (currentItemRow.length > 0) {
            itemRows.push(currentItemRow);
          }
          currentItemRow = [item];
          currentItemTop = rect.top;
        } else {
          currentItemRow.push(item);
        }
      });

      if (currentItemRow.length > 0) {
        itemRows.push(currentItemRow);
      }

      // Animate each row of items
      for (let i = 0; i < itemRows.length; i++) {
        await animateRow(itemRows[i], i);

        // Small delay between rows
        await new Promise(resolve => setTimeout(resolve, 40));
      }

      // For category items, manually animate their links with character animation
      sortedItems.forEach((item, index) => {
        const link = item.querySelector('a');
        if (link && !link.classList.contains('alien-animating')) {
          setTimeout(() => {
            prepTextForAnimation(link);
          }, index * 50); // Staggered delay for links
        }
      });
    }
  }
};

